902	    throw new HttpError(400, 'request body must be a JSON object');
903	  }
904	  return payload as Record<string, unknown>;
905	}
906	
907	function validateDraftInput(data: Record<string, unknown>): DraftInput {
908	  if (typeof data.title !== 'string') {
909	    throw new HttpError(400, 'title must be a string');
910	  }
911	  const title = data.title.trim();
912	  if (title.length === 0) {
913	    throw new HttpError(400, 'title must not be empty or only whitespace');
914	  }
915	  let summary = '';
916	  if (Object.prototype.hasOwnProperty.call(data, 'summary')) {
917	    if (typeof data.summary !== 'string') throw new HttpError(400, 'summary must be a string when provided');
918	    summary = data.summary;
919	  }
920	  if (typeof data.body !== 'string') {
921	    throw new HttpError(400, 'body must be a string');
922	  }
923	  return { title, summary, body: data.body };
924	}
925	
926	// Updates carry the version the editor loaded; stale versions are rejected.
927	// As with creation, summary may be omitted (saved as empty string) but a
928	// present non-string summary is a 400.
929	function validateUpdateInput(data: Record<string, unknown>): DraftInput & { version: number } {
930	  const fields = validateDraftInput(data);
931	  if (typeof data.version !== 'number' || !Number.isInteger(data.version) || data.version < 0) {
932	    throw new HttpError(400, 'version must be a non-negative integer');
933	  }
